import{_ as a,c as o,o as r,a0 as t}from"./chunks/framework.C1J0Vcxi.js";const i="/assets/%E5%91%A8%E6%8A%A5%E5%85%AD-1.Cv-jpYH3.png",b=JSON.parse('{"title":"第六周：星光二平台调试尝试、复现embassy移植","description":"","frontmatter":{"title":"第六周：星光二平台调试尝试、复现embassy移植","date":"2025-12-6"},"headers":[],"relativePath":"周报-Oveln/archive/2025-12-6-周报六.md","filePath":"周报-Oveln/archive/2025-12-6-周报六.md"}'),s={name:"周报-Oveln/archive/2025-12-6-周报六.md"};function l(n,e,c,d,h,u){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第六周工作总结" tabindex="-1">第六周工作总结 <a class="header-anchor" href="#第六周工作总结" aria-label="Permalink to &quot;第六周工作总结&quot;">​</a></h1><h2 id="embassy-移植复现" tabindex="-1">Embassy 移植复现 <a class="header-anchor" href="#embassy-移植复现" aria-label="Permalink to &quot;Embassy 移植复现&quot;">​</a></h2><ul><li><strong>串口烧录</strong>: 通过串口烧录<code>https://github.com/liu0fanyi/async-summary</code>中提供的固件成功复现embassy移植</li></ul><h2 id="星光二平台调试" tabindex="-1">星光二平台调试 <a class="header-anchor" href="#星光二平台调试" aria-label="Permalink to &quot;星光二平台调试&quot;">​</a></h2><ul><li><strong>J-link调试尝试</strong>: 串口调试的方式测试程序手段过于不自由，查找网上资料找到有J-link调试的先例</li><li><strong>当下结果</strong>: 成功用J-link连接<code>U74</code>大核，可能是因为<code>u-boot</code>时小核已经休眠，无法找到</li><li><strong>下一步</strong>: 使用社区开源方案（比官方sdk先进）<code>u-boot+opensbi</code>编译固件，手动修改<code>u-boot</code>，在<code>u-boot</code>阶段阻塞小核，使<code>J-link</code>连接上</li></ul><p>社区的方案在<code>spl</code>阶段就已经初始化<code>J-tag</code>端口，而官方在<code>u-boot</code>阶段做这个操作 本项目的目标是将RTOS在S76小核上替换u-boot，所以使用开源社区的上游<code>u-boot</code>是正确的</p><h2 id="固件编译" tabindex="-1">固件编译 <a class="header-anchor" href="#固件编译" aria-label="Permalink to &quot;固件编译&quot;">​</a></h2><ul><li><strong>编译固件</strong>: 使用官方<code>opensbi</code>+上游<code>u-boot</code>编译出spl固件，烧录到芯片后成功显示日志 <img src="'+i+'" alt="alt text"></li></ul><h2 id="学习平台以及启动阶段相关知识" tabindex="-1">学习平台以及启动阶段相关知识 <a class="header-anchor" href="#学习平台以及启动阶段相关知识" aria-label="Permalink to &quot;学习平台以及启动阶段相关知识&quot;">​</a></h2><h3 id="相关资料" tabindex="-1">相关资料 <a class="header-anchor" href="#相关资料" aria-label="Permalink to &quot;相关资料&quot;">​</a></h3><ul><li><a href="https://bbs.scumaker.org/t/topic/465" target="_blank" rel="noreferrer">[记录] Boot JH7110 From Scratch</a></li><li><a href="https://doc.rvspace.org/VisionFive2/PDF/VisionFive2_SW_TRM.pdf" target="_blank" rel="noreferrer">昉·星光 2单板计算机软件技术参考手册</a></li><li><a href="https://doc.rvspace.org/VisionFive2/FAQ/VisionFive_2/j_link.html" target="_blank" rel="noreferrer">RVspace 昉·星光 2常见问题集</a></li><li><a href="https://doc.rvspace.org/VisionFive2/PDF/VisionFive2_QSG.pdf" target="_blank" rel="noreferrer">昉·星光 2单板计算机快速参考手册</a></li><li><a href="https://forum.rvspace.org/t/jtag-ports/890" target="_blank" rel="noreferrer">社区帖子-JTAG ports?</a></li></ul>',11)])])}const p=a(s,[["render",l]]);export{b as __pageData,p as default};
